const payload = $input.first().json;
const items = Array.isArray(payload.opportunities) ? payload.opportunities : [];
const date = new Date(payload.generated_at || Date.now()).toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' });
const lines = ['ALVERON LABS | DAILY OPPORTUNITY BRIEFING', date, '', `New review queue: ${items.length} ranked opportunities`, ''];
for (const [index, item] of items.entries()) {
  const pay = item.compensation_min != null ? `${item.compensation_currency || ''} ${item.compensation_min}${item.compensation_max != null && item.compensation_max !== item.compensation_min ? ` - ${item.compensation_max}` : ''}`.trim() : 'Pay not stated';
  lines.push(`${index + 1}. ${item.title}`);
  lines.push(`Priority ${item.priority_score}/100 | Fit ${item.fit_score ?? 'not scored'} | Quality ${item.quality.score}/100`);
  lines.push(`${item.organization_name || 'Organization not listed'} | ${item.opportunity_type.replaceAll('_', ' ')} | ${pay}`);
  lines.push(item.source_url);
  if (item.quality.blockers.length) lines.push(`Check: ${item.quality.blockers.slice(0, 2).join(' ')}`);
  lines.push('');
}
if (!items.length) lines.push('No active opportunities are currently available.');
lines.push('Review each original listing before applying. This briefing does not verify that listings are still open.');
return [{ json: { text: lines.join('\n').slice(0, 3900), count: items.length } }];
